const crypto = require('crypto');

// Same scheme as convex/lib/hmac.ts:
//   X-LendLoop-Signature = hex(HMAC-SHA256(secret, `${timestamp}.${rawBody}`))
function sign(rawBody) {
  const secret = $env.LENDLOOP_HMAC_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('LENDLOOP_HMAC_SECRET is missing or shorter than 32 characters in the n8n container.');
  }
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  return { timestamp, signature };
}

// A GET has an empty body, so the signature covers `${timestamp}.` only.
return [{ json: sign('') }];

// Convex returns only loans that still need today's reminder, so running the
// workflow twice in one day does not email anyone twice.
const { loans } = $input.first().json;
if (!Array.isArray(loans)) throw new Error('Unexpected response from /n8n/overdue-loans: no loans array.');

const appUrl = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
return loans.map((loan) => {
  const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
  return {
    json: {
      loanId: loan.loanId,
      idempotencyKey: loan.idempotencyKey,
      to: loan.borrower.email,
      subject: `Reminder: please return the ${loan.toolName}`,
      text:
        `Hi ${loan.borrower.name},\n\n` +
        `The ${loan.toolName} you borrowed was due back on ${loan.endDate} (${days} ago). ` +
        `Please return it to the lender, who can then mark it returned.\n` +
        `Your loans: ${appUrl}/requests\n\nLendLoop`,
    },
  };
});

const crypto = require('crypto');

// Same scheme as convex/lib/hmac.ts:
//   X-LendLoop-Signature = hex(HMAC-SHA256(secret, `${timestamp}.${rawBody}`))
function sign(rawBody) {
  const secret = $env.LENDLOOP_HMAC_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('LENDLOOP_HMAC_SECRET is missing or shorter than 32 characters in the n8n container.');
  }
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
  return { timestamp, signature };
}

// One result per loan: "sent", or "failed" with the reason (the email node
// keeps going on errors so one bad address does not stop the batch).
// Convex stores one row per idempotency key (loanId:date), so a retried or
// repeated write-back updates that row instead of adding a second one.
const BATCH_SIZE = 100; // Convex accepts up to 100 reminders per request.
const loans = $('One email per overdue loan').all();

const reminders = $input.all().map((item, index) => {
  const loan = loans[item.pairedItem?.item ?? index].json;
  const error = item.json.error;
  const result = {
    idempotencyKey: loan.idempotencyKey,
    loanId: loan.loanId,
    status: error ? 'failed' : 'sent',
    channel: 'email',
  };
  if (error) result.error = String(error.message ?? error).slice(0, 300);
  return result;
});

const requests = [];
for (let start = 0; start < reminders.length; start += BATCH_SIZE) {
  const rawBody = JSON.stringify({ reminders: reminders.slice(start, start + BATCH_SIZE) });
  requests.push({ json: { rawBody, ...sign(rawBody) } });
}
return requests;
